import type { Metadata } from "next";
import { Suspense } from "react";
import { getTranslations } from "next-intl/server";

import { getUsageOverview } from "@/actions/usage";
import { UsageEmptyState } from "@/components/usage/usage-empty-state";
import { UsageChart } from "@/components/usage/usage-chart";
import { UsageRecordsTable } from "@/components/usage/usage-records-table";
import { UsageSummaryCards } from "@/components/usage/usage-summary-cards";
import {
  PageHeader,
  PageHeaderContent,
  PageHeaderDescription,
  PageHeaderTitle,
} from "@/components/ui/page-header";

export async function generateMetadata(): Promise<Metadata> {
  const t = await getTranslations("usage");
  return { title: t("meta.title") };
}

export default async function UsagePage() {
  const t = await getTranslations("usage");

  return (
    <div className="container mx-auto space-y-8 px-4 py-8">
      <PageHeader>
        <PageHeaderContent>
          <PageHeaderTitle>{t("page.title")}</PageHeaderTitle>
          <PageHeaderDescription>{t("page.description")}</PageHeaderDescription>
        </PageHeaderContent>
      </PageHeader>

      <Suspense fallback={null}>
        <UsageOverviewSection />
      </Suspense>
    </div>
  );
}

async function UsageOverviewSection() {
  const t = await getTranslations("usage");
  const result = await getUsageOverview();

  if (!result.success) {
    return (
      <UsageEmptyState
        title={t("unavailable.title")}
        description={result.error}
      />
    );
  }

  const { data } = result;

  return (
    <div className="space-y-8">
      <UsageSummaryCards
        initialPeriodSummary={data.currentPeriod}
        plan={data.plan}
        billingMode={data.billingMode}
        quota={data.quota}
        trial={data.trial}
      />
      <UsageChart points={data.daily} />

      <UsageRecordsTable records={data.records} />
    </div>
  );
}

import { Skeleton } from "@/components/ui/skeleton";

export default function UsageLoading() {
  return (
    <div className="container mx-auto space-y-8 px-4 py-8">
      <div className="space-y-2">
        <Skeleton className="h-7 w-32" />
        <Skeleton className="h-4 w-80" />
      </div>

      <div className="space-y-4">
        <Skeleton className="h-9 w-64" />
        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
          {Array.from({ length: 4 }).map((_, index) => (
            <Skeleton key={index} className="h-24 rounded-lg" />
          ))}
        </div>
      </div>

      <Skeleton className="h-96 rounded-lg" />
    </div>
  );
}

"use server";

/**
 * Usage actions — thin reads over the execution boundary and the
 * billing package's entitlement/trial reads.
 *
 * No business math lives here: `summarizeExecutions`/`listExecutions`
 * (`@intelligo-dev/executions`) own the token/charge aggregation, and
 * `getQuotaThresholds`/`getTrialStatus`/`getWorkspaceBilling`
 * (`@intelligo-dev/billing`) own quota, trial, and plan state. This file
 * only authenticates the caller, calls those, and reshapes the result
 * for the page and its components.
 *
 * Error fallbacks are translated (`getTranslations("usage")`, ADR-0010)
 * and always generic — a thrown `Error#message` is never surfaced to
 * the UI, since it can carry internals (SQL, hostnames).
 */

import { getTranslations } from "next-intl/server";

import { requireWorkspace } from "@intelligo-dev/auth";
import {
  getQuotaThresholds,
  getTrialStatus,
  getWorkspaceBilling,
} from "@intelligo-dev/billing";
import {
  listExecutions,
  summarizeExecutions,
  summarizeExecutionsByDay,
} from "@intelligo-dev/executions";

export type UsagePeriod = "7d" | "30d" | "current";

export type UsagePeriodSummary = {
  tokensUsed: number;
  /**
   * The charged amount for the period, in whatever unit the
   * deployment's billing settings charge in (`chargedMnt` on the
   * underlying execution/usage rows — the field name carries one
   * deployment's currency choice, not a framework assumption). Render
   * it as a plain number; a product that wants a currency symbol adds
   * one in its own copy of this component.
   */
  chargedAmount: number;
  requestCount: number;
};

export type UsageQuotaState = {
  percentage: number;
  warningThreshold: boolean;
  criticalThreshold: boolean;
};

export type UsageTrialState = {
  hasTrialCredits: boolean;
  status: "active" | "depleted" | "converted" | "expired" | "none";
  creditsRemaining: number;
  initialCredits: number;
  percentageRemaining: number;
};

export type UsagePlan = {
  name: string;
  slug: string;
};

export type UsageRecord = {
  id: string;
  capability: string;
  status: "running" | "settling" | "succeeded" | "failed" | "refused";
  model: string | null;
  totalTokens: number | null;
  chargedAmount: number | null;
  startedAt: string; // ISO
  durationMs: number | null;
};

export type UsageDailyPoint = {
  /** `YYYY-MM-DD`, UTC. */
  date: string;
  tokensUsed: number;
  requestCount: number;
};

export type UsageOverview = {
  plan: UsagePlan;
  billingMode: "subscription" | "credit";
  currentPeriod: UsagePeriodSummary;
  quota: UsageQuotaState;
  trial: UsageTrialState;
  /** One point per day in the current period, gaps filled with zero. */
  daily: UsageDailyPoint[];
  records: UsageRecord[];
};

export type ActionResult<T> =
  | { success: true; data: T }
  | { success: false; error: string };

/**
 * Windows are computed in UTC because the per-day read model buckets
 * in UTC (`summarizeExecutionsByDay`). Mixing the two — a local month
 * boundary against UTC buckets — silently produces a leading or
 * trailing day that belongs to the wrong period, and the size of the
 * error depends on where the reader is sitting.
 */
function periodWindow(period: UsagePeriod): { from: Date; to: Date } {
  const to = new Date();

  if (period === "current") {
    return {
      from: new Date(Date.UTC(to.getUTCFullYear(), to.getUTCMonth(), 1)),
      to,
    };
  }

  const from = new Date(to);
  from.setUTCDate(from.getUTCDate() - (period === "7d" ? 7 : 30));
  return { from, to };
}

async function summarizePeriod(
  workspaceId: string,
  period: UsagePeriod
): Promise<UsagePeriodSummary> {
  const summary = await summarizeExecutions(workspaceId, periodWindow(period));
  return {
    tokensUsed: summary.totals.totalTokens,
    chargedAmount: summary.totals.chargedMnt,
    requestCount: summary.totals.count,
  };
}

/**
 * Day-by-day series for the period, with absent days filled in as
 * zero. The read model omits days nothing ran on (see
 * `summarizeExecutionsByDay`); a chart needs the gaps, because a flat
 * stretch and a missing stretch look identical once they are drawn.
 */
function fillDailyGaps(
  rows: Array<{ date: string; totalTokens: number; count: number }>,
  window: { from: Date; to: Date }
): UsageDailyPoint[] {
  const byDate = new Map(rows.map((row) => [row.date, row]));
  const points: UsageDailyPoint[] = [];

  const cursor = new Date(
    Date.UTC(
      window.from.getUTCFullYear(),
      window.from.getUTCMonth(),
      window.from.getUTCDate()
    )
  );
  const end = Date.UTC(
    window.to.getUTCFullYear(),
    window.to.getUTCMonth(),
    window.to.getUTCDate()
  );

  while (cursor.getTime() <= end) {
    const date = cursor.toISOString().slice(0, 10);
    const row = byDate.get(date);
    points.push({
      date,
      tokensUsed: row?.totalTokens ?? 0,
      requestCount: row?.count ?? 0,
    });
    cursor.setUTCDate(cursor.getUTCDate() + 1);
  }

  return points;
}

/**
 * Full initial load for the usage page: the current-month summary,
 * quota/trial/plan state, and the most recent execution records.
 */
export async function getUsageOverview(): Promise<ActionResult<UsageOverview>> {
  const t = await getTranslations("usage");

  try {
    const { workspace } = await requireWorkspace();

    const window = periodWindow("current");

    const [currentPeriod, quota, trial, billing, recent, daily] =
      await Promise.all([
        summarizePeriod(workspace.id, "current"),
        getQuotaThresholds(workspace.id),
        getTrialStatus(workspace.id),
        getWorkspaceBilling(workspace.id),
        listExecutions({ workspaceId: workspace.id, limit: 25 }),
        summarizeExecutionsByDay(workspace.id, window),
      ]);

    return {
      success: true,
      data: {
        plan: {
          name: billing.plan?.name ?? "Free",
          slug: billing.plan?.slug ?? "free",
        },
        billingMode: billing.billingMode,
        currentPeriod,
        quota,
        trial: {
          hasTrialCredits: trial.hasTrialCredits,
          status: trial.status,
          creditsRemaining: trial.creditsRemaining,
          initialCredits: trial.initialCredits,
          percentageRemaining: trial.percentageRemaining,
        },
        daily: fillDailyGaps(daily, window),
        records: recent.map((execution) => ({
          id: execution.id,
          capability: execution.capability,
          status: execution.status as UsageRecord["status"],
          model: execution.model,
          totalTokens: execution.totalTokens,
          chargedAmount: execution.chargedMnt,
          startedAt: execution.startedAt.toISOString(),
          durationMs: execution.durationMs,
        })),
      },
    };
  } catch {
    return {
      success: false,
      // Always the translated key — a raw Error#message can carry
      // internals (SQL, hostnames) to the UI.
      error: t("errors.loadOverview"),
    };
  }
}

/**
 * Re-summarize just the current-period tile for a different window,
 * called from the client-side period selector. Quota/trial/plan state
 * and the records table are not period-dependent, so they are not
 * refetched here.
 */
export async function getUsagePeriodSummary(
  period: UsagePeriod
): Promise<ActionResult<UsagePeriodSummary>> {
  const t = await getTranslations("usage");

  try {
    const { workspace } = await requireWorkspace();
    const data = await summarizePeriod(workspace.id, period);
    return { success: true, data };
  } catch {
    return {
      success: false,
      error: t("errors.loadSummary"),
    };
  }
}

"use client";

import { useState, useTransition } from "react";
import { useFormatter, useTranslations } from "next-intl";

import { CURRENCY } from "@/lib/billing-config";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Progress } from "@/components/ui/progress";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
  StatCard,
  StatCardAction,
  StatCardHeader,
  StatCardLabel,
  StatCardValue,
} from "@/components/ui/stat-card";
import { StatusBadge } from "@/components/ui/status-badge";

import {
  getUsagePeriodSummary,
  type UsagePeriod,
  type UsagePeriodSummary,
  type UsagePlan,
  type UsageQuotaState,
  type UsageTrialState,
} from "@/actions/usage";

const PERIODS: UsagePeriod[] = ["7d", "30d", "current"];

export function UsageSummaryCards({
  initialPeriodSummary,
  plan,
  billingMode,
  quota,
  trial,
}: {
  initialPeriodSummary: UsagePeriodSummary;
  plan: UsagePlan;
  billingMode: "subscription" | "credit";
  quota: UsageQuotaState;
  trial: UsageTrialState;
}) {
  const t = useTranslations("usage");
  const format = useFormatter();
  const [period, setPeriod] = useState<UsagePeriod>("current");
  const [summary, setSummary] = useState(initialPeriodSummary);
  const [isPending, startTransition] = useTransition();

  function handlePeriodChange(next: string) {
    const nextPeriod = next as UsagePeriod;
    setPeriod(nextPeriod);

    startTransition(async () => {
      const result = await getUsagePeriodSummary(nextPeriod);
      if (result.success) {
        setSummary(result.data);
      }
    });
  }

  const quotaBadge = quota.criticalThreshold
    ? {
        label: t("summaryCards.quotaBadge.limitReached"),
        status: "destructive" as const,
      }
    : quota.warningThreshold
      ? {
          label: t("summaryCards.quotaBadge.nearingLimit"),
          status: "warning" as const,
        }
      : {
          label: t("summaryCards.quotaBadge.withinLimit"),
          status: "neutral" as const,
        };

  return (
    <div className="space-y-4">
      <Tabs value={period} onValueChange={handlePeriodChange}>
        <TabsList>
          {PERIODS.map((value) => (
            <TabsTrigger key={value} value={value} disabled={isPending}>
              {t(`summaryCards.periods.${value}`)}
            </TabsTrigger>
          ))}
        </TabsList>
      </Tabs>

      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <StatCard aria-busy={isPending}>
          <StatCardHeader>
            <StatCardLabel>{t("summaryCards.tokensUsed")}</StatCardLabel>
            <StatCardValue>{format.number(summary.tokensUsed)}</StatCardValue>
          </StatCardHeader>
        </StatCard>

        <StatCard aria-busy={isPending}>
          <StatCardHeader>
            <StatCardLabel>{t("summaryCards.chargedAmount")}</StatCardLabel>
            <StatCardValue>
              {format.number(summary.chargedAmount, {
                style: "currency",
                currency: CURRENCY,
                maximumFractionDigits: 0,
              })}
            </StatCardValue>
          </StatCardHeader>
        </StatCard>

        <StatCard aria-busy={isPending}>
          <StatCardHeader>
            <StatCardLabel>{t("summaryCards.requests")}</StatCardLabel>
            <StatCardValue>{format.number(summary.requestCount)}</StatCardValue>
          </StatCardHeader>
        </StatCard>

        <StatCard>
          <StatCardHeader>
            <StatCardLabel>{t("summaryCards.planQuota")}</StatCardLabel>
            <StatCardAction>
              <StatusBadge status={quotaBadge.status}>
                {quotaBadge.label}
              </StatusBadge>
            </StatCardAction>
          </StatCardHeader>
          <CardContent className="space-y-2">
            <Progress value={Math.min(quota.percentage, 100)} />
            <p className="text-xs text-muted-foreground">
              {billingMode === "credit"
                ? t("summaryCards.quotaAllowanceCredit", {
                    percentage: quota.percentage,
                    planName: plan.name,
                  })
                : t("summaryCards.quotaAllowance", {
                    percentage: quota.percentage,
                    planName: plan.name,
                  })}
            </p>
          </CardContent>
        </StatCard>
      </div>

      {trial.hasTrialCredits && trial.status === "active" ? (
        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium text-muted-foreground">
              {t("summaryCards.trialCredits")}
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-2">
            <div className="flex items-baseline justify-between text-sm">
              <span>
                {t("summaryCards.trialRemaining", {
                  count: format.number(trial.creditsRemaining),
                })}
              </span>
              <span className="text-muted-foreground">
                {t("summaryCards.trialOf", {
                  count: format.number(trial.initialCredits),
                })}
              </span>
            </div>
            <Progress value={Math.min(trial.percentageRemaining, 100)} />
          </CardContent>
        </Card>
      ) : null}
    </div>
  );
}

"use client";

/**
 * Tokens used per day across the current period.
 *
 * One series over time, so: an area chart in a single hue, no legend
 * (the heading names the series), and a recessive grid. Not a bar per
 * day — thirty bars encode the same thing while making the shape of a
 * month harder to read than a filled line does.
 *
 * Hand-drawn SVG rather than a charting library. A registry item is
 * source a consumer owns, and one small chart is not worth committing
 * every installer to a chart dependency, its version, and its own
 * theming story. The trade is that this is deliberately one chart type,
 * not a chart toolkit: a product that grows a real analytics surface
 * should install the library it wants and replace this file.
 *
 * Colour comes from `--primary`, so it follows the app's theme in both
 * light and dark rather than carrying its own palette. Identity is
 * never colour-alone here — there is one series, it is named in the
 * heading, and every value is also in the table underneath (visually
 * hidden, but present for screen readers and for copy-paste).
 */

import { useId, useState } from "react";
import { useFormatter, useTranslations } from "next-intl";

import type { UsageDailyPoint } from "@/actions/usage";

const VIEWBOX_WIDTH = 720;
const VIEWBOX_HEIGHT = 180;
const PADDING_TOP = 8;
const PADDING_BOTTOM = 20;

interface UsageChartProps {
  points: UsageDailyPoint[];
}

export function UsageChart({ points }: UsageChartProps) {
  const t = useTranslations("usage");
  const format = useFormatter();
  const gradientId = useId();
  const [hovered, setHovered] = useState<number | null>(null);

  // A period with a single day has no line to draw, and an all-zero
  // period would divide by zero below.
  if (points.length < 2) return null;

  const max = Math.max(...points.map((point) => point.tokensUsed), 1);
  const plotHeight = VIEWBOX_HEIGHT - PADDING_TOP - PADDING_BOTTOM;
  const step = VIEWBOX_WIDTH / (points.length - 1);

  const x = (index: number) => index * step;
  const y = (value: number) =>
    PADDING_TOP + plotHeight - (value / max) * plotHeight;

  const line = points
    .map((point, index) => `${x(index)},${y(point.tokensUsed)}`)
    .join(" ");
  const area = `${line} ${VIEWBOX_WIDTH},${PADDING_TOP + plotHeight} 0,${PADDING_TOP + plotHeight}`;

  const active = hovered === null ? null : points[hovered];
  const firstDate = new Date(`${points[0]!.date}T00:00:00Z`);
  const lastDate = new Date(`${points[points.length - 1]!.date}T00:00:00Z`);

  const shortDate = (date: Date) =>
    format.dateTime(date, { month: "short", day: "numeric", timeZone: "UTC" });

  return (
    <figure className="space-y-2">
      <figcaption className="text-sm font-medium text-muted-foreground">
        {t("chart.title")}
      </figcaption>

      <div className="relative">
        <svg
          viewBox={`0 0 ${VIEWBOX_WIDTH} ${VIEWBOX_HEIGHT}`}
          className="h-44 w-full"
          role="img"
          aria-label={t("chart.ariaLabel")}
          preserveAspectRatio="none"
          onMouseLeave={() => setHovered(null)}
        >
          <defs>
            <linearGradient id={gradientId} x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor="var(--primary)" stopOpacity="0.28" />
              <stop offset="100%" stopColor="var(--primary)" stopOpacity="0" />
            </linearGradient>
          </defs>

          {/* Recessive grid: three lines, no axis furniture. */}
          {[0, 0.5, 1].map((fraction) => (
            <line
              key={fraction}
              x1="0"
              x2={VIEWBOX_WIDTH}
              y1={PADDING_TOP + plotHeight * fraction}
              y2={PADDING_TOP + plotHeight * fraction}
              stroke="var(--border)"
              strokeWidth="1"
              vectorEffect="non-scaling-stroke"
            />
          ))}

          <polygon points={area} fill={`url(#${gradientId})`} />
          <polyline
            points={line}
            fill="none"
            stroke="var(--primary)"
            strokeWidth="2"
            strokeLinejoin="round"
            strokeLinecap="round"
            vectorEffect="non-scaling-stroke"
          />

          {hovered !== null ? (
            <>
              <line
                x1={x(hovered)}
                x2={x(hovered)}
                y1={PADDING_TOP}
                y2={PADDING_TOP + plotHeight}
                stroke="var(--border)"
                strokeWidth="1"
                vectorEffect="non-scaling-stroke"
              />
              <circle
                cx={x(hovered)}
                cy={y(points[hovered]!.tokensUsed)}
                r="4"
                fill="var(--primary)"
                stroke="var(--background)"
                strokeWidth="2"
                vectorEffect="non-scaling-stroke"
              />
            </>
          ) : null}

          {/* Hit targets: full-height columns, so the pointer finds a
              day anywhere in its slice rather than only on the line. */}
          {points.map((point, index) => (
            <rect
              key={point.date}
              x={x(index) - step / 2}
              y={0}
              width={step}
              height={VIEWBOX_HEIGHT}
              fill="transparent"
              onMouseEnter={() => setHovered(index)}
            />
          ))}
        </svg>

        {active ? (
          <div
            className="pointer-events-none absolute top-0 rounded-md border bg-popover px-2 py-1 text-xs shadow-sm"
            style={{
              left: `${(hovered! / (points.length - 1)) * 100}%`,
              transform: "translateX(-50%)",
            }}
          >
            <p className="font-medium">
              {shortDate(new Date(`${active.date}T00:00:00Z`))}
            </p>
            <p className="text-muted-foreground">
              {t("chart.tokensOnDay", { tokens: active.tokensUsed })}
            </p>
          </div>
        ) : null}
      </div>

      <div className="flex justify-between text-xs text-muted-foreground">
        <span>{shortDate(firstDate)}</span>
        <span>{shortDate(lastDate)}</span>
      </div>

      {/* The same numbers, reachable without the chart. */}
      <table className="sr-only">
        <caption>{t("chart.tableCaption")}</caption>
        <thead>
          <tr>
            <th scope="col">{t("chart.columns.date")}</th>
            <th scope="col">{t("chart.columns.tokens")}</th>
            <th scope="col">{t("chart.columns.requests")}</th>
          </tr>
        </thead>
        <tbody>
          {points.map((point) => (
            <tr key={point.date}>
              <th scope="row">{point.date}</th>
              <td>{format.number(point.tokensUsed)}</td>
              <td>{format.number(point.requestCount)}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </figure>
  );
}

import { getFormatter, getTranslations } from "next-intl/server";

import { Badge } from "@/components/ui/badge";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { CURRENCY } from "@/lib/billing-config";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";

import type { UsageRecord } from "@/actions/usage";

import { UsageEmptyState } from "./usage-empty-state";

const STATUS_VARIANT: Record<
  UsageRecord["status"],
  "default" | "secondary" | "destructive" | "outline"
> = {
  succeeded: "default",
  running: "secondary",
  settling: "secondary",
  failed: "destructive",
  refused: "outline",
};

export async function UsageRecordsTable({
  records,
}: {
  records: UsageRecord[];
}) {
  const t = await getTranslations("usage");
  const format = await getFormatter();
  const empty = t("recordsTable.empty");

  if (records.length === 0) {
    return (
      <UsageEmptyState
        title={t("recordsTable.emptyTitle")}
        description={t("recordsTable.emptyDescription")}
      />
    );
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle>{t("recordsTable.title")}</CardTitle>
      </CardHeader>
      <CardContent>
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>{t("recordsTable.columns.started")}</TableHead>
              <TableHead>{t("recordsTable.columns.capability")}</TableHead>
              <TableHead className="hidden md:table-cell">
                {t("recordsTable.columns.model")}
              </TableHead>
              <TableHead>{t("recordsTable.columns.status")}</TableHead>
              <TableHead className="hidden text-right sm:table-cell">
                {t("recordsTable.columns.tokens")}
              </TableHead>
              <TableHead className="text-right">
                {t("recordsTable.columns.chargedAmount")}
              </TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {records.map((record) => (
              <TableRow key={record.id}>
                <TableCell className="whitespace-nowrap text-muted-foreground">
                  {format.dateTime(new Date(record.startedAt), {
                    dateStyle: "medium",
                    timeStyle: "short",
                  })}
                </TableCell>
                <TableCell>
                  {record.capability}
                  {/* The model column is hidden on small screens, so
                      the primary cell carries it there. */}
                  <span className="block truncate text-xs text-muted-foreground md:hidden">
                    {record.model ?? empty}
                  </span>
                </TableCell>
                <TableCell className="hidden md:table-cell">
                  {record.model ?? empty}
                </TableCell>
                <TableCell>
                  <Badge variant={STATUS_VARIANT[record.status]}>
                    {t(`recordsTable.status.${record.status}`)}
                  </Badge>
                </TableCell>
                <TableCell className="hidden text-right sm:table-cell">
                  {record.totalTokens !== null
                    ? format.number(record.totalTokens)
                    : empty}
                </TableCell>
                <TableCell className="text-right">
                  {record.chargedAmount !== null
                    ? format.number(record.chargedAmount, {
                        style: "currency",
                        currency: CURRENCY,
                        maximumFractionDigits: 0,
                      })
                    : empty}
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </CardContent>
    </Card>
  );
}

